// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(0) && nonOwner != address(this) && nonOwner != address(c));
        vm.assume(nonOwner != c.owner());
        amount = bound(amount, 1, address(c).balance + 1 ether);

        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(nonOwner, 0);

        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        vm.deal(nonOwner, 0);
        try c.withdraw(amount) {
            assertTrue(address(c).balance == balanceBefore);
        } catch {
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}
